test('I22-05 changed source bytes with spoofed digest metadata block before approval', async (t) => {
  const { request, reader } = await fixture(t)
  let approvalCalls = 0
  const authority = roles.createRoleAuthority({
    bindings: [request.manifest.stages[0].roleAuthority,
      { path: 'decision.json', sha256: request.manifest.stages[0].roleAuthority.decision.sha256,
        revision: 'r1' }],
    verifyApproval: async () => { approvalCalls++; return true },
  })
  const injected = { read: async (path) => {
    const record = await reader.read(path)
    return path === 'plan.md' ? { ...record, bytes: Buffer.concat([record.bytes,
      Buffer.from('unapproved appended material\n')]) } : record
  } }
  issue(await roles.resolveRole({ ...request, reader: injected, authority }), 'ROLE_SOURCE_DRIFT')
  assert.equal(approvalCalls, 0)
})

